diff --git a/src/qwen38_matvec.metal b/src/qwen38_matvec.metal
index 26f3a63..b89d081 100644
--- a/src/qwen38_matvec.metal
+++ b/src/qwen38_matvec.metal
@@ -312,3 +312,110 @@ INDEXED_KERNEL(q38_matvec_indexed_iq2_xxs, Q38Iq2Xxs)
 INDEXED_KERNEL(q38_matvec_indexed_q2_k, Q38Q2K)
